package com.adent.clinical.service;
import com.adent.clinical.api.EncounterRequest; import com.adent.audit.service.AuditService; import com.adent.clinical.domain.*; import com.adent.clinical.repository.*; import com.adent.patient.domain.Patient; import com.adent.patient.repository.PatientRepository; import com.adent.shared.exception.*; import com.adent.shared.security.CurrentUser; import com.adent.staff.repository.StaffRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.OffsetDateTime; import java.util.*;
@Service
public class EncounterService {
 private final CurrentUser current; private final EncounterRepository encounters; private final ClinicalRecordRepository records; private final PatientRepository patients; private final StaffRepository staff; private final AuditService audit;
 public EncounterService(CurrentUser c,EncounterRepository e,ClinicalRecordRepository r,PatientRepository p,StaffRepository s,AuditService a){current=c;encounters=e;records=r;patients=p;staff=s;audit=a;}
 @Transactional public Encounter create(EncounterRequest r){UUID t=current.tenantId();Patient p=patients.findByIdAndTenantId(r.patientId(),t).orElseThrow(()->new NotFoundException("Paciente no encontrado"));staff.findByIdAndTenantId(r.professionalStaffId(),t).orElseThrow(()->new NotFoundException("Profesional no encontrado"));ClinicalRecord cr=records.findByTenantIdAndPatientId(t,p.getId()).orElseThrow(()->new BusinessException("El paciente no tiene historia clínica"));Encounter e=new Encounter();e.setTenantId(t);e.setClinicalRecordId(cr.getId());e.setPatientId(p.getId());e.setProfessionalStaffId(r.professionalStaffId());e.setAssistantStaffId(r.assistantStaffId());e.setRoomId(r.roomId());e.setAppointmentId(r.appointmentId());e.setEncounteredAt(r.encounteredAt()==null?OffsetDateTime.now():r.encounteredAt());e.setAlertsSnapshot(p.getClinicalAlerts());apply(e,r);Encounter saved=encounters.save(e);audit.log("ENCOUNTER_CREATED","Encounter",saved.getId(),"Atención creada en BORRADOR");return saved;}
 @Transactional public Encounter updateDraft(UUID id,EncounterRequest r){Encounter e=get(id);if(e.getStatus()!=EncounterStatus.DRAFT)throw new BusinessException("Solo una atención en BORRADOR puede modificarse directamente");apply(e,r);return encounters.save(e);}
 @Transactional public Encounter finalizeEncounter(UUID id){Encounter e=get(id);if(e.getStatus()!=EncounterStatus.DRAFT)throw new BusinessException("La atención ya no está en borrador");e.setStatus(EncounterStatus.FINALIZED);e.setClosedAt(OffsetDateTime.now());e.setClosedByUsername(current.username());Encounter saved=encounters.save(e);audit.log("ENCOUNTER_FINALIZED","Encounter",saved.getId(),"Atención cerrada");return saved;}
 @Transactional public Encounter addendum(UUID finalizedId,EncounterRequest r){Encounter original=get(finalizedId);if(original.getStatus()==EncounterStatus.DRAFT)throw new BusinessException("Primero debe finalizar la atención original");if(!original.getPatientId().equals(r.patientId()))throw new BusinessException("La adenda debe pertenecer al mismo paciente");Encounter e=create(r);e.setStatus(EncounterStatus.ADDENDUM);e.setAddendumToId(original.getId());e.setClosedAt(OffsetDateTime.now());e.setClosedByUsername(current.username());Encounter saved=encounters.save(e);audit.log("ENCOUNTER_ADDENDUM","Encounter",saved.getId(),"Adenda de " + original.getId());return saved;}
 @Transactional(readOnly=true) public List<Encounter> byPatient(UUID patientId){patients.findByIdAndTenantId(patientId,current.tenantId()).orElseThrow(()->new NotFoundException("Paciente no encontrado"));return encounters.findByTenantIdAndPatientIdOrderByEncounteredAtDesc(current.tenantId(),patientId);}
 private Encounter get(UUID id){return encounters.findByIdAndTenantId(id,current.tenantId()).orElseThrow(()->new NotFoundException("Atención no encontrada"));}
 private void apply(Encounter e,EncounterRequest r){e.setChiefComplaint(r.chiefComplaint());e.setAnamnesis(r.anamnesis());e.setClinicalExam(r.clinicalExam());e.setDentalAssessment(r.dentalAssessment());e.setTreatmentPlanSummary(r.treatmentPlanSummary());e.setProceduresSummary(r.proceduresSummary());e.setIndications(r.indications());e.setEvolution(r.evolution());e.setNextAttentionAt(r.nextAttentionAt());}
}
